from pathlib import Path
import json,hashlib,joblib
import pandas as pd,numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=Path('artifacts/light-experiment-20261115');s=json.loads((p/'summary.json').read_text())
lines=['# Thử nghiệm ánh sáng — 15/11/2026','','## Kết luận','','**Chưa đề xuất thay mô hình đang dùng.** Thêm ánh sáng chưa giúp các mô hình học máy vượt Persistence trên W04. Không triển khai model, không gửi lệnh bơm và không thay firmware. Tất cả bundle thử nghiệm có `automatic_irrigation_approved=false`, `can_trigger_pump=false`, version riêng bị inference production v2 từ chối.','','## Nguồn và quy tắc đã cố định trước khi chạy','','Train toàn bộ cửa sổ đủ điều kiện W01; validation W02+W03; test W04. Không fit, chọn siêu tham số hoặc chọn đặc trưng bằng W04. W01–W03 cùng chu kỳ tưới nên validation chỉ độc lập về phiên/thời gian, không độc lập về chu kỳ. W04 thuộc chu kỳ mới nhưng cùng cây/chậu/cảm biến, và đã được xem trước ở lượt đánh giá cũ: đây là holdout mở rộng mang tính thăm dò, cần W05 chưa sử dụng để xác nhận.','','So sánh LR/RF có và không có ánh sáng trên **cùng hàng train, validation, test**. RF cố định 150 cây, depth 8, leaf 10, seed 42; LR mặc định. Không random-split, không tuning sau khi xem W04. Có Persistence và ngoại suy tuyến tính. Bộ đối chứng mới fit toàn W01 khác mô hình W01 đóng băng cũ vốn fit phần train nội bộ; không nhầm hai loại kết quả.','','Dùng CSV phút đã chốt làm nền, bổ sung median ADC từ raw JSONL theo timestamp thiết bị; không ghi đè raw hay CSV cũ. W03 chỉ dùng 956 mẫu đúng phiên. Một phút có ADC thiếu/không hợp lệ sẽ giữ NaN; không nội suy. Không dùng ADC tương lai để lọc cửa sổ. Giữ toàn bộ quy tắc loại phút tưới, mất dữ liệu, đổi boot và loại cửa sổ có tưới trong khoảng dự đoán của v2. W04 vẫn loại trước lần tưới đầu vì lịch sử trước phiên chưa được xác nhận.','','5 đặc trưng thêm: ADC hiện tại, lag 5/15 phút, mean 15 phút gồm phút hiện tại và 14 phút trước, slope=(ADC hiện tại−lag15)/15. Cần 16 phút lịch sử đầy đủ. Giá trị phút chỉ khả dụng sau khi phút đóng; timestamp trong CSV là đầu bin như pipeline cũ. ADC 4095 giữ nguyên là giá trị bị giới hạn dải, không đổi sang lux, không coi là giá trị ánh sáng chính xác vượt trần. Có kịch bản nhạy cảm loại lịch sử chứa mẫu chạm trần, dùng nguyên model đã fit.','','## Chất lượng ánh sáng','','| Phiên | Mẫu | Có ADC | ADC=4095 | Tỷ lệ | Phút thiếu ADC |','|---|---:|---:|---:|---:|---:|']
for name,q in s['light_quality'].items():lines.append(f"| {name} | {q['raw_rows']} | {q['present_light']} | {q['saturated_4095']} | {q['saturation_percent']:.2f}% | {q['minute_missing_adc']} |")
lines+=['','W02 có 3 phút thiếu ADC do không có telemetry ở các phút đó. 100% mẫu thô có ADC không đồng nghĩa chuỗi thời gian liên tục. `light_lux` không được suy ra. Thử che cảm biến garden-01 ngày 15/11: bình thường 688, che 2074, bỏ che 651; hỗ trợ chiều ADC tăng khi tối hơn trong lần thử, không hiệu chuẩn độ rọi và không xác định ngưỡng nhu cầu cây.','','## MAE trên W04 (điểm phần trăm soil)','','| Horizon | Số cửa sổ test | LR không sáng | LR có sáng | RF không sáng | RF có sáng | Persistence | Ngoại suy |','|---|---:|---:|---:|---:|---:|---:|---:|']
for r in s['results']:
 m=r['test_mae_pp'];lines.append(f"| {r['horizon_minutes']} phút | {r['counts']['W04']['common_windows']} | "+' | '.join(f'{m[k]:.4f}' for k in ['linear_regression_control','linear_regression_light','random_forest_control','random_forest_light','persistence','linear_extrapolation'])+' |')
lines+=['','Validation chọn **Persistence cho cả 30 và 60 phút**. RF cải thiện rất nhỏ khi thêm ánh sáng, vẫn thua baseline rất xa; không chứng minh cải thiện có ý nghĩa thống kê từ các cửa sổ chồng lấn. Không báo khoảng tin cậy theo giả định từng cửa sổ độc lập.','','## Phân tích RF tổng quát hóa kém','','RF60 W01 cũ MAE≈6,625 so với Persistence≈1,005 trên W04; kết quả kiểm tra mới tương tự. Kiểm tra phạm vi fit/test ở từng đặc trưng được lưu trong report.json. Độ ẩm W04 sau tưới cao hơn vùng soil hiện tại đã học từ W01; RF dự đoán quanh vùng mục tiêu W01 thấp. Ánh sáng không tạo thêm nhãn soil cao hoặc thêm chu kỳ tưới cho train. Đây là bằng chứng phù hợp với lệch phân bố và thiếu đa dạng chu kỳ, chưa phải chứng minh nguyên nhân duy nhất. Không quy lỗi riêng cho cảm biến ánh sáng.','','| Horizon | Train W01 | Validation W02 | Validation W03 | Test ngoài vùng soil fit |','|---|---:|---:|---:|---:|']
for r in s['results']:lines.append(f"| {r['horizon_minutes']} | {r['counts']['W01']['common_windows']} | {r['counts']['W02']['common_windows']} | {r['counts']['W03']['common_windows']} | {r['ranges']['soil_pct']['test_outside_fit_rows']} |")
lines+=['','## Độ nhạy với bão hòa','','Giữ nguyên model, chỉ xét các cửa sổ W04 không có ADC chạm 4095 trong 16 phút lịch sử. Không dùng phân tích này để chọn model hay thay đổi tập test chính.','','| Horizon | Cửa sổ còn | RF không sáng | RF có sáng | Persistence |','|---|---:|---:|---:|---:|']
for r in s['results']:
 a=r['saturation_sensitivity'];m=a['mae_pp'];lines.append(f"| {r['horizon_minutes']} | {a['rows']} | {m['random_forest_control']:.4f} | {m['random_forest_light']:.4f} | {m['persistence']:.4f} |")
lines+=['','## Quan hệ ánh sáng–soil','','Pearson trên các phút soil hợp lệ đã đối soát và trên sai phân một phút liền kề (không nối qua gap):','','| Phiên | Mức ADC–soil | Sai phân ADC–soil |','|---|---:|---:|']
for n,q in s['light_quality'].items():lines.append(f"| {n} | {q['soil_adc_pearson']:.4f} | {q['soil_adc_change_pearson']:.4f} |")
lines+=['','Các hệ số chỉ mô tả dữ liệu, không chứng minh ánh sáng gây khô đất. Giờ trong ngày, nhiệt độ/độ ẩm không khí, phân bố nước, tự tương quan và bão hòa có thể gây nhiễu. Chưa dùng kiểm định p-value từ các mẫu thời gian phụ thuộc.','','## Tái lập','','```bash','PYTHONPATH=ai .venv-ai/bin/python -m smart_green_ai.light_experiment --output artifacts/light-experiment-new-run','PYTHONPATH=ai .venv-ai/bin/python -m pytest ai/tests/test_light_features.py -q','node backend/tests/dashboard_controls.test.cjs','```','','Output phải là thư mục mới; script từ chối ghi đè. Chạy từ gốc repository có W01–W04. Bundle `.joblib` chỉ nạp từ nguồn tin cậy. `summary.json` lưu versions, input SHA-256, chất lượng và MAE; mỗi horizon có 4 bundle, CSV dự đoán chung và report.json. Không cấu hình các bundle này vào backend production.','','Mã mới: `ai/smart_green_ai/light_features.py`, `light_experiment.py`. AI v2 và mô hình cũ không sửa. Dashboard thêm đồ thị ADC riêng và xu hướng theo kiểm tra thực nghiệm garden-01, chặn suy diễn khi cũ/thiếu/reset/bão hòa; chưa gán thiếu/thừa sáng. Nhật ký thêm các mốc quan sát có timestamp và xuất trong ZIP.','','Hướng dẫn W05: [W05_LIGHT_COLLECTION_GUIDE.md](W05_LIGHT_COLLECTION_GUIDE.md).']
Path('docs/LIGHT_EXPERIMENT_2026-11-15.md').write_text('\n'.join(lines)+'\n')
# Independently verify saved fitted artifacts reproduce exported predictions.
from smart_green_ai.light_features import light_supervised
for r in s['results']:
 h=r['horizon_minutes'];test,_=light_supervised(pd.read_csv(p/'W04-minutes.csv'),h);pred=pd.read_csv(p/f'horizon-{h}/predictions.csv')
 for modelpath in (p/f'horizon-{h}').glob('*.joblib'):
  b=joblib.load(modelpath);k=b['metadata']['model_name'];v=np.clip(b['model'].predict(test[b['metadata']['features']]),0,100)
  assert np.allclose(v,pred[k]) and np.isclose(np.abs(v-test.target).mean(),r['test_mae_pp'][k])
  assert not b['metadata']['can_trigger_pump']
fig,ax=plt.subplots(figsize=(10,5));x=np.arange(2);width=.22
for i,k in enumerate(['random_forest_control','random_forest_light','persistence']):ax.bar(x+(i-1)*width,[r['test_mae_pp'][k] for r in s['results']],width,label=k)
ax.set_xticks(x,['30 min','60 min']);ax.set_ylabel('MAE (soil percentage points)');ax.set_title('W04 exploratory holdout • paired test windows');ax.legend();ax.grid(axis='y',alpha=.2);fig.tight_layout();fig.savefig(p/'mae-comparison.png',dpi=160)
print('Report generated; saved models and exported MAE independently verified')
